def find_magic_sequence(n):
    from itertools import product
    solutions = []
    for seq in product(range(n+1), repeat=n):
        if sum(seq) != n:
            continue
        ok = True
        for i, val in enumerate(seq):
            if seq.count(i) != val:
                ok = False
                break
        if ok:
            solutions.append(list(seq))
    return solutions

print(find_magic_sequence(3))
